"use client";

import { useId, type ReactNode } from "react";
import { cn } from "@/lib/utils";
import { AmountInput, type AmountInputProps } from "./amount-input";
import { FieldSet, FieldLabel, FieldDescription, FieldError } from "@/components/ui/field";

export interface AssetInputProps extends Omit<AmountInputProps, "className"> {
  /** Visible label connected to the amount input. */
  label: ReactNode;
  /** Token identity or your app's picker trigger. */
  asset?: ReactNode | undefined;
  /** Supporting text, such as a fiat estimate. Connected via aria-describedby. */
  description?: ReactNode | undefined;
  /** Validation message. Marks the input invalid and connects the message. */
  error?: ReactNode | undefined;
  /** Balance, Max actions, or other app-owned supporting content. */
  footer?: ReactNode | undefined;
  /** Applied to the field container. */
  className?: string | undefined;
  /** Applied to the amount input. */
  inputClassName?: string | undefined;
}

export function AssetInput({
  label,
  asset,
  description,
  error,
  footer,
  className,
  inputClassName,
  id,
  disabled,
  "aria-describedby": describedBy,
  "aria-invalid": ariaInvalid,
  ...props
}: AssetInputProps) {
  const generatedId = useId();
  const inputId = id ?? generatedId;
  const hasDescription = description != null && description !== false;
  const hasError = error != null && error !== false && error !== "";
  const invalid = hasError || ariaInvalid;
  const descriptionIds = [
    describedBy,
    hasDescription ? `${inputId}-description` : undefined,
    hasError ? `${inputId}-error` : undefined,
  ].filter(Boolean).join(" ") || undefined;

  return (
    <FieldSet
      disabled={disabled}
      data-slot="asset-input"
      data-invalid={invalid || undefined}
      className={cn(
        "m-0 grid min-w-0 gap-3 rounded-xl border border-input bg-muted/30 p-4",
        "focus-within:border-ring data-[invalid=true]:border-destructive disabled:opacity-50",
        className
      )}
    >
      <FieldLabel htmlFor={inputId} className="text-sm font-medium text-muted-foreground">
        {label}
      </FieldLabel>
      <div className="flex min-w-0 items-center gap-3">
        {asset != null && <div className="min-w-0 max-w-[50%] shrink-0">{asset}</div>}
        <AmountInput
          {...props}
          id={inputId}
          disabled={disabled}
          aria-describedby={descriptionIds}
          aria-invalid={invalid}
          className={cn(
            "h-auto flex-1 rounded-sm border-0 bg-transparent px-0 py-1 text-right text-3xl tracking-tight shadow-none focus-visible:ring-2 disabled:opacity-100 md:text-3xl dark:bg-transparent",
            inputClassName
          )}
        />
      </div>
      {hasDescription && (
        <FieldDescription id={`${inputId}-description`}>
          {description}
        </FieldDescription>
      )}
      {footer != null && <div className="flex min-w-0 flex-wrap items-center gap-2 text-xs text-muted-foreground">{footer}</div>}
      {hasError && (
        <FieldError id={`${inputId}-error`}>
          {error}
        </FieldError>
      )}
    </FieldSet>
  );
}

"use client";

import {
  useEffect,
  useRef,
  useState,
  type ComponentProps,
  type CSSProperties,
  type ReactNode,
} from "react";
import { cn } from "@/lib/utils";
import { Input } from "@/components/ui/input";

// Props come from the app's own Input rather than a bare <input>, so variants
// the app added to it (bskts has an `amount` variant for money forms) pass
// straight through.
export interface AmountInputProps
  extends Omit<
    ComponentProps<typeof Input>,
    "type" | "inputMode" | "value" | "defaultValue" | "onChange" | "min" | "max" | "step"
  > {
  /** Unformatted decimal string. Empty and incomplete values are valid while editing. */
  value: string;
  /** Receives accepted edits without numeric conversion or rounding. */
  onValueChange?: ((value: string) => void) | undefined;
  /** Maximum fractional digits. Omit for unrestricted precision; 0 allows integers only. */
  decimals?: number | undefined;
  /**
   * Shown inside the field at the end, e.g. a unit such as "USDC". The text
   * is padded so it never runs under it. Decorative: name the unit in the
   * field's label too.
   */
  suffix?: ReactNode | undefined;
}

/** Checks editing syntax, not whether an amount is ready for a transaction. */
export function isAmountInputValue(value: string, decimals?: number): boolean {
  if (decimals !== undefined && (!Number.isInteger(decimals) || decimals < 0)) {
    return false;
  }
  if (!/^[0-9]*(\.[0-9]*)?$/.test(value)) return false;
  const point = value.indexOf(".");
  return point === -1 || decimals === undefined ||
    (decimals > 0 && value.length - point - 1 <= decimals);
}

// AmountInput stays hook-free (the tests call it as a plain function and read
// the element it returns). Only a suffixed field mounts this measuring part.
// It measures the suffix so the input's end padding clears it at any font or
// label length. Before the first measurement (and during SSR) a 3.5rem guess
// keeps short units like "ETH" or "USDC" clear.
function SuffixedAmountInput({
  input,
  suffix,
}: {
  input: (suffixPadding: string) => ReactNode;
  suffix: ReactNode;
}) {
  const ref = useRef<HTMLSpanElement>(null);
  const [width, setWidth] = useState<number | null>(null);
  useEffect(() => {
    const el = ref.current;
    if (!el || typeof ResizeObserver === "undefined") return;
    const observer = new ResizeObserver(([entry]) => {
      if (entry) setWidth(entry.contentRect.width);
    });
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  return (
    <span data-slot="amount-input-group" className="relative flex w-full min-w-0 items-center">
      {input(width === null ? "3.5rem" : `calc(${width}px + 1.25rem)`)}
      <span
        ref={ref}
        aria-hidden="true"
        className="pointer-events-none absolute inset-y-0 end-3 flex items-center text-xs text-muted-foreground"
      >
        {suffix}
      </span>
    </span>
  );
}

export function AmountInput({
  value,
  onValueChange,
  decimals,
  readOnly = !onValueChange,
  disabled,
  className,
  placeholder = "0",
  suffix,
  style,
  ...props
}: AmountInputProps) {
  const input = (suffixPadding?: string) => (
    <Input
      autoComplete="off"
      spellCheck={false}
      size={1}
      {...props}
      data-slot="amount-input"
      type="text"
      inputMode="decimal"
      value={value}
      placeholder={placeholder}
      readOnly={readOnly}
      disabled={disabled}
      onChange={(event) => {
        const next = event.target.value;
        if (!disabled && !readOnly && isAmountInputValue(next, decimals)) {
          onValueChange?.(next);
        }
      }}
      className={cn(
        "font-mono tabular-nums",
        suffixPadding && "pe-(--amount-input-suffix)",
        className
      )}
      style={
        suffixPadding
          ? ({ ...style, "--amount-input-suffix": suffixPadding } as CSSProperties)
          : style
      }
    />
  );

  if (suffix == null || suffix === false) return input();
  return <SuffixedAmountInput input={input} suffix={suffix} />;
}

"use client";

import { useState } from "react";
import { AssetInput } from "./asset-input";
import { Button } from "@/components/ui/button";
import { NativeSelect, NativeSelectOption } from "@/components/ui/native-select";

const assets = {
  USDC: { decimals: 6, spendable: "1250.123456" },
  ETH: { decimals: 18, spendable: "0.249999999999999999" },
};

export default function AssetInputDemo() {
  const [symbol, setSymbol] = useState<keyof typeof assets>("USDC");
  const [value, setValue] = useState("");
  const asset = assets[symbol];

  return (
    <div className="grid w-full max-w-md gap-3">
      <AssetInput
        label="Sell"
        value={value}
        onValueChange={setValue}
        decimals={asset.decimals}
        asset={
          <NativeSelect
            aria-label="Sell asset"
            value={symbol}
            onChange={(event) => {
              setSymbol(event.target.value as keyof typeof assets);
              setValue("");
            }}
            className="max-w-full"
          >
            <NativeSelectOption value="USDC">USDC</NativeSelectOption>
            <NativeSelectOption value="ETH">ETH</NativeSelectOption>
          </NativeSelect>
        }
        description="Enter an amount to request a quote."
        footer={
          <>
            <span className="min-w-0 break-all">Available: {asset.spendable} {symbol}</span>
            <Button
              type="button"
              variant="ghost"
              size="xs"
              onClick={() => setValue(asset.spendable)}
              className="ml-auto"
            >
              Max
            </Button>
          </>
        }
      />
      <p className="text-xs text-muted-foreground">Sample balances. The app supplies the picker and spendable amount.</p>
    </div>
  );
}

export function AssetInputStatesDemo() {
  const [value, setValue] = useState("1500");
  return (
    <div className="grid w-full max-w-md gap-3">
      <AssetInput
        label="Sell"
        value={value}
        onValueChange={setValue}
        decimals={6}
        asset={<span className="font-medium">USDC</span>}
        error={Number(value) > 1250 ? "Insufficient USDC balance." : undefined}
        footer="Balance: 1,250 USDC"
      />
      <AssetInput
        label="Receive (estimated)"
        value="0.42"
        readOnly
        asset={<span className="font-medium">ETH</span>}
        description="Example quote supplied by the app."
      />
      <AssetInput
        label="Deposit"
        value=""
        disabled
        asset={<Button type="button" variant="outline" disabled>Select asset</Button>}
        description="Connect your wallet to continue."
      />
    </div>
  );
}

export function AssetInputPairDemo() {
  const [first, setFirst] = useState("");
  const [second, setSecond] = useState("");
  return (
    <div className="grid w-full max-w-md gap-3">
      <AssetInput label="First deposit" value={first} onValueChange={setFirst} decimals={18} asset={<span className="font-medium">ETH</span>} />
      <AssetInput label="Second deposit" value={second} onValueChange={setSecond} decimals={6} asset={<span className="font-medium">USDC</span>} />
    </div>
  );
}
